const errTrigger = $('Error Trigger').item.json;
const wf = errTrigger.workflow || {};
const exec = errTrigger.execution || {};
const err = exec.error || {};

const workflowId = String(wf.id || 'desconocido');
const workflowNombre = wf.name || 'Workflow desconocido';
const ejecucionId = String(exec.id || 'desconocido');
const nodoFallido = exec.lastNodeExecuted || (err.node && err.node.name) || null;

function sanitizar(texto) {
  let t = String(texto || 'Sin mensaje de error');
  // Redactar tokens Bearer/Basic
  t = t.replace(/(Bearer|Basic)\s+[A-Za-z0-9._-]+/gi, '$1 [REDACTADO]');
  // Redactar api_key/token/password/secret en query strings
  t = t.replace(/([?&](api[_-]?key|token|password|pwd|secret)=)[^&\s]+/gi, '$1[REDACTADO]');
  // Redactar strings largos tipo base64/JWT (>=32 chars)
  t = t.replace(/[A-Za-z0-9+/]{32,}={0,2}/g, '[REDACTADO]');
  return t.slice(0, 500);
}

const mensajeError = sanitizar(err.message);

return {
  json: {
    id: $('Generar ID del Evento').item.json.eventoId,
    tipo: 'n8n.flujo_fallido',
    fecha: new Date().toISOString(),
    origen: `n8n/${workflowNombre}`,
    datos: {
      workflow_id: workflowId,
      workflow_nombre: workflowNombre,
      ejecucion_id: ejecucionId,
      ...(nodoFallido ? { nodo_fallido: nodoFallido } : {}),
      mensaje_error: mensajeError,
    },
  },
};
